const tickers = [
  'NVDA', 'MSFT', 'GOOGL', 'AMZN', 'META',
  'AVGO', 'TSM', 'ASML', 'MU', 'AMD',
  'ORCL', 'ANET', 'SMCI', 'VRT', 'ARM'
];

return tickers.map(symbol => ({ json: { symbol } }));

const items = $input.all();
const tickers = $('tickerArr').all();

const fields = items.map((item, i) => {
  const j = item.json;
  const symbol = tickers[i].json.symbol;
  const arrow = j.Change >= 0 ? "▲" : "▼";
  return {
    name: symbol,
    value: `${arrow} $${j.Current.toFixed(2)} (${j["Percent Change"].toFixed(2)}%)\nOpen: $${j.Open.toFixed(2)}`,
    inline: true
  };
});

const payload = {
  content: `AI Watchlist — ${new Date().toLocaleDateString("en-US")}`,
  embeds: [
    {
      title: "Daily Market Snapshot",
      color: 5814783,
      fields,
      footer: { text: "Auto-generated · Not financial advice" },
      timestamp: new Date().toISOString()
    }
  ]
};

return [{ json: payload }];
